const centers=[];
for(let x=-3;x<=3;x++)for(let y=-3;y<=3;y++)for(let z=-3;z<=3;z++)centers.push([(x+(random()-.5)*.8)*2.4,(y+(random()-.5)*.8)*2.4,(z+(random()-.5)*.8)*2.4]);
