 const point=(p,c,size)=>{positions.push(...p);colors.push(...c);sizes.push(size);};const line=(a,b,c)=>{lines.push(...a,...b);lineColors.push(...c,...c);lineSizes.push(1,1);};
 if(activeTab==='processes'){drawReaction(point,line);}else if(lab){labPoints.forEach((p,i)=>{const c=p.map((v,k)=>v*scale-baseOrigin[k]);point(c,i===labObserver?[1,.75,.4,1]:[.55,.82,1,1],2);line([0,0,0],c,[.4,.7,.85,.28]);for(let j=0;j<45;j++){const a=j*2.4,r=.23*Math.sqrt(j/45);point([c[0]+Math.cos(a)*r,c[1]+Math.sin(a)*r*.3,c[2]+Math.sin(a)*r],[.65,.8,1,.65],.22);}});
 }else{const clustering=Math.max(0,Math.min(1,(chapter-6.3)/2.4));for(const p of particles){const center=centers[p.c],loc=p.local;const xyz=p.base.map((v,k)=>{const diffuse=v*scale;const bound=center[k]*scale+loc[k];return diffuse*(1-clustering)+bound*clustering-baseOrigin[k];});let rgb,alpha,size=p.size;if(era<2){rgb=[.35,.45,.68];alpha=.12;}else if(era<6){rgb=p.h<.3?[1,.85,.53]:p.h<.7?[1,.42,.16]:[.44,.75,1];alpha=.6;size*=1.8;}else if(era===6){rgb=[1,.62,.28];alpha=.25;}else if(era===7){rgb=[.3,.48,.7];alpha=.15;size*=.7;}else{rgb=p.h<.3?[1,.74,.42]:[.57,.79,1];alpha=.82;size*=.8;}point(xyz,[...rgb,alpha],size);}if(era>=8){centers.forEach((c,i)=>{const xyz=c.map((v,k)=>v*scale-baseOrigin[k]);point(xyz,i%3?[.65,.84,1,.85]:[1,.8,.52,.9],.65);});}}
