function frame(now){const dt=lastFrame?Math.min((now-lastFrame)/1000,.1):0;lastFrame=now;if(!document.hidden){if(reactionPlaying&&activeTab==='processes'){reactionProgress=Math.min(1,reactionProgress+dt*.12);if(reactionProgress>=1)reactionPlaying=false;updateReaction();}if(playing){chapter=Math.min(11,chapter+dt*.085*+$('speed').value);if(chapter>=11){playing=false;updateUI();}if(now-uiTime>90){updateUI();uiTime=now;}}const renderState=[chapter,angle,pitch,zoom,observer,labObserver,labScale,activeTab,reactionProgress,$('reaction').value,$('grid').checked,$('vectors').checked,canvas.clientWidth,devicePixelRatio].join('|');if(renderState!==lastRenderState&&now-lastRenderTime>=32){render(now);lastRenderState=renderState;lastRenderTime=now;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
