const reactionDescriptions={quarks:'Three valence quarks (u, u, d) become confined in a proton. The real proton also contains gluons and a dynamic sea of quark–antiquark pairs; those are omitted.',deuterium:'A proton and neutron bind into deuterium, releasing a photon: p + n → ²H + γ. In the early universe, surviving deuterium opens paths toward helium.',hydrogen:'Radiative recombination: p + e⁻ → H + γ. This is atomic binding, distinct from weak nuclear electron capture. Cloud dots symbolize one electron; their radial density is illustrative, not a calculated wavefunction. Actual cosmological recombination includes multiple levels and radiative-transfer effects.',carbon:'Triple-alpha burning in stars: two helium-4 nuclei transiently form beryllium-8; a third joins to produce excited carbon-12, which can radiate. Three alpha particles provide six protons and six neutrons.'};
function updateReaction(){$('reaction-progress').value=reactionProgress;$('reaction-play').textContent=reactionPlaying?'Ⅱ Pause reaction':'▶ Play reaction';$('reaction-text').textContent=reactionDescriptions[$('reaction').value];$('reaction-stage').textContent=reactionProgress<.35?'1 / Initial constituents':reactionProgress<.7?'2 / Approach and interaction':'3 / Bound product and released energy';}
$('reaction').onchange=()=>{reactionProgress=0;reactionPlaying=false;updateReaction();};$('reaction-progress').oninput=e=>{reactionProgress=+e.target.value;reactionPlaying=false;updateReaction();};$('reaction-play').onclick=()=>{if(reactionProgress>=1)reactionProgress=0;reactionPlaying=!reactionPlaying;updateReaction();};$('reaction-reset').onclick=()=>{reactionProgress=0;reactionPlaying=false;updateReaction();};updateReaction();
function drawReaction(point,line){const type=$('reaction').value,p=reactionProgress,smooth=x=>{const t=Math.max(0,Math.min(1,x));return t*t*(3-2*t);},q=smooth((p-.15)/.6),gold=[1,.67,.27,1],blue=[.35,.65,1,1];const mix=(a,b,f)=>a.map((v,k)=>v+(b[k]-v)*f);function nucleus(center,count,offset=0){for(let n=0;n<count;n++){const a=n*2.4,r=count>1?.5:0,loc=[r*Math.cos(a),r*Math.sin(a),((n%3)-1)*.23];point(center.map((v,k)=>v+loc[k]),(n+offset)%2?blue:gold,3);}}if(type==='quarks'){const ends=[[0,.65,0],[-.6,-.35,0],[.6,-.35,0]],starts=[[-5,2,1],[4,3,-2],[0,-4,2]],out=starts.map((s,i)=>mix(s,ends[i],q));out.forEach((pos,i)=>point(pos,i===2?blue:gold,3));if(p>.4){for(let i=0;i<3;i++)line(out[i],out[(i+1)%3],[.5,.7,.9,.5]);}}else if(type==='deuterium'){const a=mix([-5,1,0],[-.45,0,0],q),b=mix([5,-1,0],[.45,0,0],q);point(a,gold,3);point(b,blue,3);}else if(type==='hydrogen'){point([0,0,0],gold,3);if(p<.7)point(mix([6,3,0],[1.4,0,0],q),[.5,1,1,1],1.4);else{for(let i=0;i<140;i++){const r=1.1+1.7*((Math.sin(i*13.8)+1)/2),a=i*2.399,z=1-2*(i+.5)/140,b=Math.sqrt(1-z*z);point([r*Math.cos(a)*b,r*Math.sin(a)*b,r*z],[.3,.9,1,.18],.8);}}}else{for(let j=0;j<3;j++){const a=j*Math.PI*2/3,start=[Math.cos(a)*5,Math.sin(a)*5,0],end=[Math.cos(a)*.65,Math.sin(a)*.65,j*.15];const f=j===2?smooth((p-.45)/.35):smooth((p-.12)/.4);nucleus(mix(start,end,f),4);}}if(p>.72&&type!=='quarks'){const r=(p-.72)*26;point([r,r*.3,0],[1,1,1,1],2);line([r-.7,r*.3,0],[r,r*.3,0],[1,1,1,.8]);}}

// Manual tab activation preserves the reader's place while browsing controls.
const matterTabs = [...document.querySelectorAll('[data-tab]')];
matterTabs.forEach((button,index) => button.addEventListener('keydown',event => {
  let target;
  if(event.key==='ArrowRight') target=(index+1)%matterTabs.length;
  else if(event.key==='ArrowLeft') target=(index+matterTabs.length-1)%matterTabs.length;
  else if(event.key==='Home') target=0;
  else if(event.key==='End') target=matterTabs.length-1;
  else return;
  event.preventDefault();matterTabs.forEach((b,i)=>b.tabIndex=i===target?0:-1);matterTabs[target].focus();
}));
